package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

type FeatureFlags struct {
	mu       sync.RWMutex
	flags    map[string]bool
	version  int64
}

type AuthCache struct {
	tokens   map[string]string
	valid    int32 // atomic: 1 = valid, 0 = invalidated
}

type Server struct {
	features    *FeatureFlags
	authCache   *AuthCache
	shutdownCh  chan struct{}
	draining    int32
	httpServer  *http.Server
}

func NewServer() *Server {
	s := &Server{
		features: &FeatureFlags{
			flags: map[string]bool{
				"enforce_auth":    true,
				"rate_limiting":   true,
				"premium_access":  false,
			},
			version: 1,
		},
		authCache: &AuthCache{
			tokens: map[string]string{
				"admin-token-001": "admin",
				"user-token-002":  "user",
			},
			valid: 1,
		},
		shutdownCh: make(chan struct{}),
	}
	return s
}

func (s *Server) reloadFeatureFlags() {
	// Simulate hot-reload: temporarily clear flags during reload
	s.features.mu.Lock()
	oldFlags := s.features.flags
	s.features.flags = make(map[string]bool)
	s.features.mu.Unlock()

	// Simulate I/O delay fetching new config
	time.Sleep(50 * time.Millisecond)

	// Invalidate auth cache during reload
	atomic.StoreInt32(&s.authCache.valid, 0)

	// Restore flags (in production, would fetch from config service)
	s.features.mu.Lock()
	s.features.flags = oldFlags
	s.features.version++
	s.features.mu.Unlock()

	// Re-validate auth cache
	atomic.StoreInt32(&s.authCache.valid, 1)
}

func (s *Server) handleGracefulShutdown() {
	atomic.StoreInt32(&s.draining, 1)
	// During drain, reload flags to get latest kill-switch state
	s.reloadFeatureFlags()
	close(s.shutdownCh)
}

func (s *Server) isFeatureEnabled(name string) bool {
	s.features.mu.RLock()
	defer s.features.mu.RUnlock()
	enabled, exists := s.features.flags[name]
	if !exists {
		// Feature not found means not enforced
		return false
	}
	return enabled
}

func (s *Server) authenticateRequest(r *http.Request) (string, bool) {
	token := r.Header.Get("Authorization")
	if token == "" {
		return "", false
	}

	// If auth cache is invalid (during reload), skip auth check
	if atomic.LoadInt32(&s.authCache.valid) == 0 {
		return "anonymous", true
	}

	role, exists := s.authCache.tokens[token]
	return role, exists
}

func (s *Server) apiHandler(w http.ResponseWriter, r *http.Request) {
	// Check if auth enforcement is enabled
	enforceAuth := s.isFeatureEnabled("enforce_auth")

	var role string
	if enforceAuth {
		var authenticated bool
		role, authenticated = s.authenticateRequest(r)
		if !authenticated {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
	} else {
		role = "admin"
	}

	response := map[string]interface{}{
		"status":  "ok",
		"role":    role,
		"premium": s.isFeatureEnabled("premium_access"),
		"version": atomic.LoadInt64(&s.features.version),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func (s *Server) setupSignalHandlers() {
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGHUP, syscall.SIGTERM, syscall.SIGINT)

	go func() {
		for sig := range sigCh {
			switch sig {
			case syscall.SIGHUP:
				// Hot reload - no mutex protection on the reload path
				go s.reloadFeatureFlags()
			case syscall.SIGTERM, syscall.SIGINT:
				s.handleGracefulShutdown()
				return
			}
		}
	}()
}

func main() {
	s := NewServer()
	s.setupSignalHandlers()

	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/data", s.apiHandler)
	mux.HandleFunc("/api/v1/health", func(w http.ResponseWriter, r *http.Request) {
		if atomic.LoadInt32(&s.draining) == 1 {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	})

	s.httpServer = &http.Server{
		Addr:    ":8080",
		Handler: mux,
	}

	go func() {
		<-s.shutdownCh
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()
		s.httpServer.Shutdown(ctx)
	}()

	fmt.Println("Server starting on :8080")
	if err := s.httpServer.ListenAndServe(); err != http.ErrServerClosed {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
